using LibraryManager.BUS;
using System.Data;

namespace LibraryManager.GUI;
public sealed class MainForm:Form
{
    readonly LibraryService service=new(); readonly TabControl tabs=new(){Dock=DockStyle.Fill};
    readonly DataGridView bookGrid=Grid(),readerGrid=Grid(),loanGrid=Grid(),lateGrid=Grid(),statsGrid=Grid();
    readonly TextBox bookName=new(){Width=210},bookGenre=new(){Width=145},readerName=new(){Width=170},readerEmail=new(){Width=205};
    readonly NumericUpDown bookStock=new(){Width=80,Minimum=0,Maximum=10000},quantity=new(){Width=70,Minimum=1,Maximum=1000,Value=1},days=new(){Width=70,Minimum=1,Maximum=365,Value=14};
    readonly DateTimePicker cardExpiry=new(){Width=140,Format=DateTimePickerFormat.Short};
    readonly ComboBox readerFilter=new(){Width=190,DropDownStyle=ComboBoxStyle.DropDownList},borrowReader=new(){Width=190,DropDownStyle=ComboBoxStyle.DropDownList},borrowBook=new(){Width=250,DropDownStyle=ComboBoxStyle.DropDownList},statusFilter=new(){Width=130,DropDownStyle=ComboBoxStyle.DropDownList};
    int? bookId,readerId,loanId;
    public MainForm(){Text="Thư Viện Số | Quản lý mượn trả sách";Width=1320;Height=850;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(246,248,251);BuildHome();BuildBooks();BuildReaders();BuildLoans();BuildReports();Controls.Add(tabs);Shown+=(_,_)=>RefreshAll();}
    static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,BackgroundColor=Color.White,BorderStyle=BorderStyle.None};
    static Label LabelFor(string s)=>new(){Text=s,AutoSize=true,Margin=new Padding(6,9,2,2)};
    static Button Btn(string s,EventHandler h)=>new Button{Text=s,AutoSize=true,Height=34,Margin=new Padding(3),BackColor=Color.White,FlatStyle=FlatStyle.Flat}.Also(b=>b.Click+=h);
    static FlowLayoutPanel Bar(int h)=>new(){Dock=DockStyle.Top,Height=h,Padding=new Padding(6),WrapContents=true};
    TabPage Page(string title){var p=new TabPage(title){Padding=new Padding(12),BackColor=BackColor};tabs.TabPages.Add(p);return p;}
    void BuildHome(){var p=Page("Tổng quan");p.Controls.Add(new Label{Text="THƯ VIỆN SỐ  |  QUẢN LÝ MƯỢN TRẢ SÁCH",Font=new Font("Segoe UI",24,FontStyle.Bold),ForeColor=Color.FromArgb(27,66,116),AutoSize=true,Location=new Point(28,28)});p.Controls.Add(new Label{Text="Quản lý đầu sách • Theo dõi thẻ độc giả • Cảnh báo quá hạn",Font=new Font("Segoe UI",14),AutoSize=true,Location=new Point(32,82)});var box=new Panel{Location=new Point(32,145),Size=new Size(610,210),BackColor=Color.White};box.Controls.Add(new Label{Text="Kết nối SQL Server",Font=new Font("Segoe UI",17,FontStyle.Bold),Location=new Point(22,18),AutoSize=true});box.Controls.Add(new Label{Text=@"Server: localhost\SQLEXPRESS  |  Database: LibraryDB",Location=new Point(22,60),AutoSize=true});box.Controls.Add(new Label{Text="Kiến trúc 3 tầng: DTO → DAL → BUS → GUI",Location=new Point(22,98),AutoSize=true});box.Controls.Add(new Label{Text="Mượn có kiểm tra hạn thẻ • Trả sách cập nhật tồn kho • Truy vấn có tham số",Location=new Point(22,136),AutoSize=true});box.Controls.Add(new Label{Text="",Name="summary",Location=new Point(22,170),AutoSize=true,Font=new Font("Segoe UI",11,FontStyle.Bold)});p.Controls.Add(box);}
    void BuildBooks(){var p=Page("Đầu sách");var top=Bar(104);top.Controls.AddRange(new Control[]{LabelFor("Tên sách"),bookName,LabelFor("Thể loại"),bookGenre,LabelFor("Số lượng"),bookStock,Btn("Thêm sách",(_,_)=>SaveBook(null)),Btn("Cập nhật",(_,_)=>SaveBook(bookId)),Btn("Xóa",(_,_)=>DeleteBook()),Btn("Làm mới",(_,_)=>LoadBooks())});p.Controls.Add(bookGrid);p.Controls.Add(top);bookGrid.SelectionChanged+=(_,_)=>SelectBook();}
    void BuildReaders(){var p=Page("Độc giả");var top=Bar(104);top.Controls.AddRange(new Control[]{LabelFor("Họ và tên"),readerName,LabelFor("Email"),readerEmail,LabelFor("Hạn thẻ"),cardExpiry,Btn("Thêm độc giả",(_,_)=>SaveReader(null)),Btn("Cập nhật",(_,_)=>SaveReader(readerId)),Btn("Xóa",(_,_)=>DeleteReader()),Btn("Làm mới",(_,_)=>LoadReaders())});p.Controls.Add(readerGrid);p.Controls.Add(top);readerGrid.SelectionChanged+=(_,_)=>SelectReader();}
    void BuildLoans(){var p=Page("Mượn / trả sách");var top=Bar(106);readerFilter.SelectedIndexChanged+=(_,_)=>LoadLoans();statusFilter.Items.AddRange(new object[]{"Tất cả","Đang mượn","Đã trả","Quá hạn"});statusFilter.SelectedIndex=0;statusFilter.SelectedIndexChanged+=(_,_)=>LoadLoans();top.Controls.AddRange(new Control[]{LabelFor("Lọc độc giả"),readerFilter,LabelFor("Trạng thái"),statusFilter,LabelFor("Độc giả mượn"),borrowReader,LabelFor("Đầu sách"),borrowBook,LabelFor("SL"),quantity,LabelFor("Số ngày"),days,Btn("Lập phiếu mượn",(_,_)=>Borrow()),Btn("Đánh dấu đã trả",(_,_)=>Return()),Btn("Tải danh sách",(_,_)=>LoadLoans())});p.Controls.Add(loanGrid);p.Controls.Add(top);loanGrid.SelectionChanged+=(_,_)=>{if(loanGrid.CurrentRow?.DataBoundItem is DataRowView r)loanId=Convert.ToInt32(r["MaPhieu"]);};}
    void BuildReports(){var p=Page("Quá hạn / thống kê");var inner=new TabControl{Dock=DockStyle.Fill};var a=new TabPage("Sách quá hạn");var b=new TabPage("Lượt mượn theo thể loại");a.Controls.Add(lateGrid);b.Controls.Add(statsGrid);inner.TabPages.Add(a);inner.TabPages.Add(b);var top=Bar(48);top.Controls.Add(Btn("Cập nhật báo cáo",(_,_)=>LoadReports()));p.Controls.Add(inner);p.Controls.Add(top);}
    void RefreshAll(){try{LoadBooks();LoadReaders();LoadLookups();LoadLoans();LoadReports();int books=service.Data.Scalar("SELECT COUNT(*) FROM dbo.DauSach"),readers=service.Data.Scalar("SELECT COUNT(*) FROM dbo.DocGia"),overdue=service.Data.Scalar("SELECT COUNT(*) FROM dbo.PhieuMuon WHERE HanTra<GETDATE() AND TrangThai<>N'Đã trả'");var label=Controls.Find("summary",true).FirstOrDefault() as Label;if(label!=null)label.Text=$"{books} đầu sách   •   {readers} độc giả   •   {overdue} phiếu quá hạn";}catch(Exception ex){Error(ex);}}
    void LoadBooks(){bookGrid.DataSource=service.Data.Books();}
    void LoadReaders(){readerGrid.DataSource=service.Data.Readers();}
    void LoadLookups(){var r=service.Data.Readers();readerFilter.DataSource=r.Copy();readerFilter.DisplayMember="HoTen";readerFilter.ValueMember="MaDocGia";readerFilter.SelectedIndex=-1;borrowReader.DataSource=r.Copy();borrowReader.DisplayMember="HoTen";borrowReader.ValueMember="MaDocGia";borrowReader.SelectedIndex=r.Rows.Count>0?0:-1;var b=service.Data.BookChoices();borrowBook.DataSource=b;borrowBook.DisplayMember="TenSach";borrowBook.ValueMember="MaSach";borrowBook.SelectedIndex=b.Rows.Count>0?0:-1;}
    int Pick(ComboBox c)=>int.TryParse(c.SelectedValue?.ToString(),out var n)?n:0;
    void LoadLoans(){loanGrid.DataSource=service.Data.Loans(Pick(readerFilter),statusFilter.SelectedItem?.ToString()??"Tất cả");}
    void LoadReports(){lateGrid.DataSource=service.Data.Overdue();statsGrid.DataSource=service.Data.GenreStats();}
    void SelectBook(){if(bookGrid.CurrentRow?.DataBoundItem is not DataRowView r)return;bookId=Convert.ToInt32(r["MaSach"]);bookName.Text=r["TenSach"].ToString();bookGenre.Text=r["TheLoai"].ToString();bookStock.Value=Convert.ToDecimal(r["SoLuongCon"]);}
    void SaveBook(int? id){try{service.ValidateBook(bookName.Text,bookGenre.Text,(int)bookStock.Value);service.Data.SaveBook(id,bookName.Text.Trim(),bookGenre.Text.Trim(),(int)bookStock.Value);LoadBooks();LoadLookups();}catch(Exception ex){Error(ex);}}
    void DeleteBook(){if(bookId is null)return;try{service.Data.DeleteBook(bookId.Value);bookId=null;LoadBooks();LoadLookups();}catch(Exception ex){Error(ex);}}
    void SelectReader(){if(readerGrid.CurrentRow?.DataBoundItem is not DataRowView r)return;readerId=Convert.ToInt32(r["MaDocGia"]);readerName.Text=r["HoTen"].ToString();readerEmail.Text=r["Email"].ToString();cardExpiry.Value=Convert.ToDateTime(r["NgayHetHanThe"]);}
    void SaveReader(int? id){try{service.ValidateReader(readerName.Text,readerEmail.Text);service.Data.SaveReader(id,readerName.Text.Trim(),readerEmail.Text.Trim(),cardExpiry.Value);LoadReaders();LoadLookups();}catch(Exception ex){Error(ex);}}
    void DeleteReader(){if(readerId is null)return;try{service.Data.DeleteReader(readerId.Value);readerId=null;LoadReaders();LoadLookups();}catch(Exception ex){Error(ex);}}
    void Borrow(){try{int reader=Pick(borrowReader),book=Pick(borrowBook);service.ValidateBorrow(reader,book,(int)quantity.Value,(int)days.Value);service.Data.Borrow(reader,book,(int)quantity.Value,(int)days.Value);LoadBooks();LoadLookups();LoadLoans();LoadReports();MessageBox.Show("Đã lập phiếu mượn và cập nhật số lượng sách.","Thành công",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){Error(ex);}}
    void Return(){if(loanId is null){MessageBox.Show("Chọn phiếu mượn cần trả.");return;}try{service.Data.Return(loanId.Value);LoadBooks();LoadLookups();LoadLoans();LoadReports();MessageBox.Show("Đã trả sách; số lượng tồn đã được cộng lại.");}catch(Exception ex){Error(ex);}}
    void Error(Exception ex)=>MessageBox.Show(ex.Message,"Thông báo",MessageBoxButtons.OK,MessageBoxIcon.Warning);
}
internal static class ControlExtensions{internal static T Also<T>(this T c,Action<T> action) where T:Control{action(c);return c;}}
